// AVTOMATIK YARATILGAN FAYL — qo'lda tahrirlamang.
// Manba: scripts/generate-demos.mjs (pnpm --filter docs demos), bloklar — blocks/<name>/
import type { ComponentType } from 'react';
import Block0 from '../../blocks/app-shell-layout/app-shell-layout';
import Block1 from '../../blocks/checkout-summary/checkout-summary';
import Block2 from '../../blocks/dashboard-stats/dashboard-stats';
import Block3 from '../../blocks/data-table-page/data-table-page';
import Block4 from '../../blocks/login/login';
import Block5 from '../../blocks/otp-verify/otp-verify';
import Block6 from '../../blocks/pricing/pricing';
import Block7 from '../../blocks/register/register';
import Block8 from '../../blocks/settings-profile/settings-profile';

export interface BlockMeta {
  title: { uz: string; en: string };
  description: { uz: string; en: string };
  /** `@akhatmirzo/ui` + `@akhatmirzo/tokens` dan tashqari kerakli paketlar */
  dependencies: string[];
  category: string;
}

export interface BlockEntry {
  component: ComponentType;
  /** Blok faylining haqiqiy manba kodi */
  source: string;
  /** blocks/ ga nisbatan yo'l */
  file: string;
  meta: BlockMeta;
}

export const blocks: Record<string, BlockEntry> = {
  "app-shell-layout": { component: Block0, file: "app-shell-layout/app-shell-layout.tsx", meta: {"title":{"uz":"Ilova qolipi","en":"App shell layout"},"description":{"uz":"AppShell, Sidebar va Header bilan to'liq boshqaruv paneli qolipi.","en":"A complete admin layout with AppShell, Sidebar and Header."},"dependencies":["@akhatmirzo/core","lucide-react"],"category":"layout"}, source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport {\n  AppShell,\n  Avatar,\n  Badge,\n  Breadcrumb,\n  Button,\n  Card,\n  DropdownMenu,\n  IconButton,\n  Input,\n  Progress,\n  Sidebar,\n} from '@akhatmirzo/ui';\nimport {\n  BarChart3,\n  Bell,\n  Boxes,\n  ChevronsUpDown,\n  CircleHelp,\n  House,\n  LogOut,\n  Megaphone,\n  Plus,\n  Search,\n  Settings,\n  ShoppingBag,\n  Store,\n  Truck,\n  User,\n  Users,\n} from 'lucide-react';\nimport { useState, type ReactNode } from 'react';\n\ninterface NavItem {\n  id: string;\n  label: string;\n  icon: ReactNode;\n  badge?: number;\n}\n\nconst MAIN_NAV: NavItem[] = [\n  { id: 'home', label: 'Bosh sahifa', icon: <House /> },\n  { id: 'orders', label: 'Buyurtmalar', icon: <ShoppingBag />, badge: 12 },\n  { id: 'products', label: 'Mahsulotlar', icon: <Boxes /> },\n  { id: 'customers', label: 'Mijozlar', icon: <Users /> },\n  { id: 'delivery', label: 'Yetkazish', icon: <Truck />, badge: 3 },\n];\n\nconst GROWTH_NAV: NavItem[] = [\n  { id: 'reports', label: 'Hisobotlar', icon: <BarChart3 /> },\n  { id: 'marketing', label: 'Marketing', icon: <Megaphone /> },\n];\n\nconst ACTIVITY = [\n  { who: 'Dilnoza Yusupova', what: '#10482 buyurtmani berdi', when: '2 daqiqa oldin' },\n  { who: 'Otabek Qodirov', what: \"#10477 to'lovini Payme orqali qildi\", when: '18 daqiqa oldin' },\n  { who: 'Malika Rahimova', what: 'yangi sharh qoldirdi — 5 yulduz', when: '1 soat oldin' },\n  { who: 'Jasur Karimov', what: '#10465 buyurtmani qaytardi', when: '3 soat oldin' },\n];\n\nconst GOALS = [\n  { label: 'Oylik savdo rejasi', value: 72 },\n  { label: 'Yetkazish vaqtida', value: 94 },\n  { label: \"Ombor to'ldirish\", value: 38 },\n];\n\nfunction UserMenu({ children }: { children: ReactNode }) {\n  return (\n    <DropdownMenu>\n      <DropdownMenu.Trigger asChild>{children}</DropdownMenu.Trigger>\n      <DropdownMenu.Content align=\"end\" className=\"w-56\">\n        <DropdownMenu.Label>akmal@chorsu.uz</DropdownMenu.Label>\n        <DropdownMenu.Item icon={<User />}>Profil</DropdownMenu.Item>\n        <DropdownMenu.Item icon={<Settings />}>Sozlamalar</DropdownMenu.Item>\n        <DropdownMenu.Item icon={<CircleHelp />}>Yordam markazi</DropdownMenu.Item>\n        <DropdownMenu.Separator />\n        <DropdownMenu.Item icon={<LogOut />} variant=\"danger\">\n          Chiqish\n        </DropdownMenu.Item>\n      </DropdownMenu.Content>\n    </DropdownMenu>\n  );\n}\n\nexport default function AppShellLayoutBlock() {\n  const [page, setPage] = useState('home');\n  const current =\n    [...MAIN_NAV, ...GROWTH_NAV].find((item) => item.id === page)?.label ?? 'Sozlamalar';\n\n  const navItem = (item: NavItem) => (\n    <Sidebar.Item\n      key={item.id}\n      icon={item.icon}\n      badge={item.badge}\n      active={page === item.id}\n      onClick={() => setPage(item.id)}\n    >\n      {item.label}\n    </Sidebar.Item>\n  );\n\n  return (\n    <AppShell sidebarStorageKey=\"chorsu-sidebar\">\n      <Sidebar>\n        <Sidebar.Header>\n          <span className=\"grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground\">\n            <Store className=\"size-5\" aria-hidden=\"true\" />\n          </span>\n          <span className=\"flex min-w-0 flex-col\">\n            <span className=\"truncate text-sm font-bold\">Chorsu Market</span>\n            <span className=\"truncate text-xs text-text-muted\">Toshkent filiali</span>\n          </span>\n        </Sidebar.Header>\n        <Sidebar.Content>\n          <Sidebar.Group label=\"Do'kon\">{MAIN_NAV.map(navItem)}</Sidebar.Group>\n          <Sidebar.Group label=\"O'sish\">{GROWTH_NAV.map(navItem)}</Sidebar.Group>\n          <Sidebar.Group label=\"Boshqaruv\">\n            <Sidebar.Item\n              icon={<Settings />}\n              active={page === 'settings'}\n              onClick={() => setPage('settings')}\n            >\n              Sozlamalar\n            </Sidebar.Item>\n          </Sidebar.Group>\n        </Sidebar.Content>\n        <Sidebar.Footer>\n          <UserMenu>\n            <button\n              type=\"button\"\n              className=\"focus-ring flex w-full items-center gap-2.5 rounded-lg p-1 text-left hover:bg-surface-muted\"\n            >\n              <Avatar name=\"Akmal Karimov\" size=\"sm\" status=\"online\" />\n              <span className=\"flex min-w-0 flex-1 flex-col\">\n                <span className=\"truncate text-sm font-medium\">Akmal Karimov</span>\n                <span className=\"truncate text-xs text-text-muted\">Administrator</span>\n              </span>\n              <ChevronsUpDown className=\"size-4 shrink-0 text-text-muted\" aria-hidden=\"true\" />\n            </button>\n          </UserMenu>\n        </Sidebar.Footer>\n      </Sidebar>\n\n      <AppShell.Main>\n        <AppShell.Header>\n          <AppShell.SidebarToggle />\n          <Breadcrumb\n            className=\"hidden min-w-0 sm:flex\"\n            items={[{ label: 'Chorsu Market', href: '#home' }, { label: current }]}\n          />\n          <div className=\"ml-auto flex items-center gap-2\">\n            <Input\n              aria-label=\"Qidirish\"\n              placeholder=\"Qidirish…\"\n              leftIcon={<Search />}\n              size=\"sm\"\n              className=\"hidden w-56 md:flex\"\n            />\n            <span className=\"relative\">\n              <IconButton variant=\"ghost\" aria-label=\"Bildirishnomalar: 3 ta yangi\">\n                <Bell />\n              </IconButton>\n              <span\n                aria-hidden=\"true\"\n                className=\"absolute top-2 right-2 size-2 rounded-full bg-danger ring-2 ring-background\"\n              />\n            </span>\n            <UserMenu>\n              <button type=\"button\" className=\"focus-ring rounded-full\" aria-label=\"Profil menyusi\">\n                <Avatar name=\"Akmal Karimov\" size=\"sm\" />\n              </button>\n            </UserMenu>\n          </div>\n        </AppShell.Header>\n\n        {/* Sahifa kontenti — o'z kengligiga qarab moslashadi */}\n        <div className=\"@container flex-1\">\n          <div className=\"flex flex-col gap-6 p-4 @3xl:p-8\">\n            <div className=\"flex flex-col gap-3 @xl:flex-row @xl:items-end @xl:justify-between\">\n              <div className=\"flex flex-col gap-1\">\n                <h1 className=\"m-0 text-2xl font-bold tracking-tight\">{current}</h1>\n                <p className=\"m-0 text-sm text-text-muted\">\n                  Xush kelibsiz, Akmal! Bugun 22-oktabr, payshanba.\n                </p>\n              </div>\n              <Button variant=\"primary\" leftIcon={<Plus />}>\n                Mahsulot qo&apos;shish\n              </Button>\n            </div>\n\n            <div className=\"grid gap-4 @2xl:grid-cols-3\">\n              {[\n                {\n                  title: 'Bugungi tushum',\n                  value: formatMoney(14_250_000),\n                  note: '+12% kechagiga nisbatan',\n                },\n                { title: 'Yangi buyurtmalar', value: '86 ta', note: '12 tasi javob kutmoqda' },\n                { title: 'Faol mijozlar', value: '2 340', note: 'Oxirgi 30 kunda' },\n              ].map((stat) => (\n                <Card key={stat.title} padding=\"sm\" className=\"gap-1\">\n                  <span className=\"text-sm text-text-muted\">{stat.title}</span>\n                  <span className=\"text-2xl font-bold tracking-tight tabular-nums\">\n                    {stat.value}\n                  </span>\n                  <span className=\"text-xs text-text-muted\">{stat.note}</span>\n                </Card>\n              ))}\n            </div>\n\n            <div className=\"grid gap-4 @4xl:grid-cols-[minmax(0,3fr)_minmax(0,2fr)]\">\n              <Card className=\"gap-4\">\n                <div className=\"flex items-center justify-between gap-2\">\n                  <h2 className=\"m-0 text-base font-semibold\">So&apos;nggi faoliyat</h2>\n                  <Badge color=\"primary\">Jonli</Badge>\n                </div>\n                <ul className=\"m-0 flex list-none flex-col gap-4 p-0\">\n                  {ACTIVITY.map((item) => (\n                    <li key={item.what} className=\"flex items-start gap-3\">\n                      <Avatar name={item.who} size=\"sm\" />\n                      <div className=\"flex min-w-0 flex-col\">\n                        <span className=\"text-sm\">\n                          <span className=\"font-medium\">{item.who}</span> {item.what}\n                        </span>\n                        <span className=\"text-xs text-text-muted\">{item.when}</span>\n                      </div>\n                    </li>\n                  ))}\n                </ul>\n              </Card>\n\n              <Card className=\"gap-5\">\n                <h2 className=\"m-0 text-base font-semibold\">Oylik maqsadlar</h2>\n                {GOALS.map((goal) => (\n                  <Progress\n                    key={goal.label}\n                    size=\"sm\"\n                    label={goal.label}\n                    value={goal.value}\n                    showValue\n                    color={goal.value >= 90 ? 'success' : goal.value < 50 ? 'warning' : 'primary'}\n                  />\n                ))}\n              </Card>\n            </div>\n          </div>\n        </div>\n      </AppShell.Main>\n    </AppShell>\n  );\n}\n" },
  "checkout-summary": { component: Block1, file: "checkout-summary/checkout-summary.tsx", meta: {"title":{"uz":"Buyurtma xulosasi","en":"Checkout summary"},"description":{"uz":"Savat ro'yxati, promokod, so'mdagi jami summa va Stepper bilan buyurtma bosqichlari.","en":"Cart list, promo code, total in so'm and checkout steps with a Stepper."},"dependencies":["@akhatmirzo/core","lucide-react"],"category":"commerce"}, source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport {\n  Badge,\n  Button,\n  Card,\n  Divider,\n  EmptyState,\n  Field,\n  IconButton,\n  Input,\n  Stepper,\n  toast,\n} from '@akhatmirzo/ui';\nimport {\n  ArrowRight,\n  Minus,\n  Plus,\n  ShieldCheck,\n  Shirt,\n  ShoppingCart,\n  Tag,\n  Trash2,\n  Truck,\n  Watch,\n  Headphones,\n  X,\n} from 'lucide-react';\nimport { useState, type ReactNode } from 'react';\n\ninterface CartItem {\n  id: string;\n  name: string;\n  variant: string;\n  icon: ReactNode;\n  price: number;\n  qty: number;\n}\n\nconst INITIAL: CartItem[] = [\n  {\n    id: 'atlas',\n    name: \"Atlas ko'ylak\",\n    variant: \"Marg'ilon atlasi · M o'lcham\",\n    icon: <Shirt />,\n    price: 389_000,\n    qty: 1,\n  },\n  {\n    id: 'watch',\n    name: 'Aqlli soat Pro',\n    variant: 'Qora · 44 mm',\n    icon: <Watch />,\n    price: 1_249_000,\n    qty: 1,\n  },\n  {\n    id: 'buds',\n    name: 'Simsiz quloqchin',\n    variant: 'Oq · shovqinni yutadi',\n    icon: <Headphones />,\n    price: 459_000,\n    qty: 2,\n  },\n];\n\nconst STEPS = [\n  { title: 'Savat' },\n  { title: 'Yetkazish', description: 'Manzil va vaqt' },\n  { title: \"To'lov\" },\n  { title: 'Tasdiqlash' },\n];\n\n/** Sinov promokodlari: kod → chegirma ulushi */\nconst PROMO_CODES: Record<string, number> = { TOSHKENT10: 0.1, YANGI15: 0.15 };\n/** Shu summadan yuqorida yetkazish bepul */\nconst FREE_DELIVERY_FROM = 1_000_000;\nconst DELIVERY_PRICE = 25_000;\n\nexport default function CheckoutSummaryBlock() {\n  const [items, setItems] = useState(INITIAL);\n  const [step, setStep] = useState(0);\n  const [promoInput, setPromoInput] = useState('');\n  const [promo, setPromo] = useState<string | null>(null);\n  const [promoError, setPromoError] = useState('');\n\n  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);\n  const discount = promo ? Math.round((subtotal * (PROMO_CODES[promo] ?? 0)) / 1000) * 1000 : 0;\n  const delivery = subtotal === 0 || subtotal >= FREE_DELIVERY_FROM ? 0 : DELIVERY_PRICE;\n  const total = subtotal - discount + delivery;\n  const count = items.reduce((sum, item) => sum + item.qty, 0);\n\n  const setQty = (id: string, qty: number) =>\n    setItems((prev) =>\n      prev.flatMap((item) => (item.id !== id ? [item] : qty > 0 ? [{ ...item, qty }] : [])),\n    );\n\n  const applyPromo = () => {\n    const code = promoInput.trim().toUpperCase();\n    if (!code) return setPromoError('Promokodni kiriting');\n    if (!(code in PROMO_CODES)) return setPromoError(\"Bunday promokod yo'q yoki muddati o'tgan\");\n    setPromo(code);\n    setPromoError('');\n    setPromoInput('');\n    toast.success(`${code} qo'llandi`, {\n      description: `${(PROMO_CODES[code] ?? 0) * 100}% chegirma`,\n    });\n  };\n\n  const stepper = (\n    <>\n      {/* Tor konteynerda — ixcham ko'rinish, kengida — to'liq qadamlar */}\n      <div className=\"@2xl:hidden\">\n        <Stepper steps={STEPS} value={step} onValueChange={setStep} compact aria-label=\"Buyurtma\" />\n      </div>\n      <div className=\"hidden @2xl:block\">\n        <Stepper\n          steps={STEPS}\n          value={step}\n          onValueChange={setStep}\n          compact={false}\n          aria-label=\"Buyurtma\"\n        />\n      </div>\n    </>\n  );\n\n  return (\n    <section className=\"@container w-full bg-background font-sans text-text\">\n      <div className=\"flex flex-col gap-8 p-4 @3xl:p-8\">\n        {stepper}\n\n        {items.length === 0 ? (\n          <Card>\n            <EmptyState\n              icon={<ShoppingCart />}\n              title=\"Savatingiz bo'sh\"\n              description=\"Katalogdan mahsulot tanlang — yetkazish 1 000 000 so'mdan bepul.\"\n              action={\n                <Button variant=\"primary\" onClick={() => setItems(INITIAL)}>\n                  Xarid qilishni davom ettirish\n                </Button>\n              }\n            />\n          </Card>\n        ) : (\n          <div className=\"grid items-start gap-6 @4xl:grid-cols-[minmax(0,1fr)_380px]\">\n            <Card padding=\"none\" className=\"overflow-hidden\">\n              <div className=\"flex items-center justify-between gap-3 border-b border-border px-5 py-4\">\n                <h2 className=\"m-0 text-lg font-semibold\">Savat</h2>\n                <Badge>{count} ta mahsulot</Badge>\n              </div>\n              <ul className=\"m-0 flex list-none flex-col p-0\">\n                {items.map((item) => (\n                  <li\n                    key={item.id}\n                    className=\"flex flex-wrap items-center gap-4 border-b border-border px-5 py-4 last:border-b-0\"\n                  >\n                    <span\n                      className=\"grid size-16 shrink-0 place-items-center rounded-xl bg-primary-soft text-primary-soft-foreground [&_svg]:size-7\"\n                      aria-hidden=\"true\"\n                    >\n                      {item.icon}\n                    </span>\n                    <div className=\"flex min-w-0 flex-1 flex-col gap-0.5\">\n                      <span className=\"font-medium\">{item.name}</span>\n                      <span className=\"text-sm text-text-muted\">{item.variant}</span>\n                      <span className=\"text-sm font-semibold tabular-nums @xl:hidden\">\n                        {formatMoney(item.price * item.qty)}\n                      </span>\n                    </div>\n                    <div className=\"flex items-center gap-3\">\n                      <div\n                        role=\"group\"\n                        aria-label={`${item.name} soni`}\n                        className=\"flex items-center rounded-lg border border-border\"\n                      >\n                        <IconButton\n                          size=\"sm\"\n                          variant=\"ghost\"\n                          aria-label=\"Kamaytirish\"\n                          disabled={item.qty <= 1}\n                          onClick={() => setQty(item.id, item.qty - 1)}\n                        >\n                          <Minus />\n                        </IconButton>\n                        <span\n                          className=\"w-8 text-center text-sm font-medium tabular-nums\"\n                          aria-live=\"polite\"\n                        >\n                          {item.qty}\n                        </span>\n                        <IconButton\n                          size=\"sm\"\n                          variant=\"ghost\"\n                          aria-label=\"Ko'paytirish\"\n                          disabled={item.qty >= 9}\n                          onClick={() => setQty(item.id, item.qty + 1)}\n                        >\n                          <Plus />\n                        </IconButton>\n                      </div>\n                      <span className=\"hidden w-32 text-right font-semibold tabular-nums @xl:block\">\n                        {formatMoney(item.price * item.qty)}\n                      </span>\n                      <IconButton\n                        size=\"sm\"\n                        variant=\"ghost\"\n                        aria-label={`${item.name} — o'chirish`}\n                        onClick={() => setQty(item.id, 0)}\n                      >\n                        <Trash2 />\n                      </IconButton>\n                    </div>\n                  </li>\n                ))}\n              </ul>\n            </Card>\n\n            <Card className=\"gap-5 @4xl:sticky @4xl:top-4\">\n              <h2 className=\"m-0 text-lg font-semibold\">Buyurtma xulosasi</h2>\n\n              {promo ? (\n                <div className=\"flex items-center justify-between gap-2 rounded-lg bg-success-soft px-3 py-2 text-sm text-success-soft-foreground\">\n                  <span className=\"flex items-center gap-2 font-medium\">\n                    <Tag className=\"size-4\" aria-hidden=\"true\" />\n                    {promo} — {(PROMO_CODES[promo] ?? 0) * 100}% chegirma\n                  </span>\n                  <IconButton\n                    size=\"sm\"\n                    variant=\"ghost\"\n                    aria-label=\"Promokodni olib tashlash\"\n                    onClick={() => setPromo(null)}\n                  >\n                    <X />\n                  </IconButton>\n                </div>\n              ) : (\n                <Field\n                  label=\"Promokod\"\n                  error={promoError}\n                  description={!promoError ? 'Sinov uchun: TOSHKENT10' : undefined}\n                >\n                  <form\n                    noValidate\n                    onSubmit={(event) => {\n                      event.preventDefault();\n                      applyPromo();\n                    }}\n                    className=\"flex gap-2\"\n                  >\n                    <Input\n                      value={promoInput}\n                      onChange={(e) => {\n                        setPromoInput(e.target.value);\n                        if (promoError) setPromoError('');\n                      }}\n                      placeholder=\"Masalan, YANGI15\"\n                      leftIcon={<Tag />}\n                      className=\"flex-1\"\n                    />\n                    <Button type=\"submit\" variant=\"outline\">\n                      Qo&apos;llash\n                    </Button>\n                  </form>\n                </Field>\n              )}\n\n              <dl className=\"m-0 flex flex-col gap-2.5 text-sm\">\n                <div className=\"flex justify-between gap-4\">\n                  <dt className=\"text-text-muted\">Mahsulotlar ({count})</dt>\n                  <dd className=\"m-0 tabular-nums\">{formatMoney(subtotal)}</dd>\n                </div>\n                {discount > 0 && (\n                  <div className=\"flex justify-between gap-4\">\n                    <dt className=\"text-text-muted\">Chegirma</dt>\n                    <dd className=\"m-0 text-success tabular-nums\">−{formatMoney(discount)}</dd>\n                  </div>\n                )}\n                <div className=\"flex justify-between gap-4\">\n                  <dt className=\"text-text-muted\">Yetkazib berish (Toshkent)</dt>\n                  <dd className=\"m-0 tabular-nums\">\n                    {delivery === 0 ? <Badge color=\"success\">Bepul</Badge> : formatMoney(delivery)}\n                  </dd>\n                </div>\n              </dl>\n\n              <Divider />\n\n              <div className=\"flex items-baseline justify-between gap-4\">\n                <span className=\"font-semibold\">Jami</span>\n                <span className=\"text-2xl font-bold tracking-tight tabular-nums\">\n                  {formatMoney(total)}\n                </span>\n              </div>\n\n              <Button\n                variant=\"primary\"\n                size=\"lg\"\n                fullWidth\n                rightIcon={<ArrowRight />}\n                disabled={step >= STEPS.length - 1}\n                onClick={() => setStep((s) => Math.min(s + 1, STEPS.length - 1))}\n              >\n                {step === 0 ? 'Rasmiylashtirish' : 'Davom etish'}\n              </Button>\n\n              <ul className=\"m-0 flex list-none flex-col gap-2 p-0 text-xs text-text-muted\">\n                <li className=\"flex items-center gap-2\">\n                  <Truck className=\"size-4 shrink-0\" aria-hidden=\"true\" />\n                  Toshkent bo&apos;ylab 1 kunda, viloyatlarga 2–3 kunda\n                </li>\n                <li className=\"flex items-center gap-2\">\n                  <ShieldCheck className=\"size-4 shrink-0\" aria-hidden=\"true\" />\n                  Click, Payme, Uzcard va Humo — xavfsiz to&apos;lov\n                </li>\n              </ul>\n            </Card>\n          </div>\n        )}\n      </div>\n    </section>\n  );\n}\n" },
  "dashboard-stats": { component: Block2, file: "dashboard-stats/dashboard-stats.tsx", meta: {"title":{"uz":"Dashboard statistikasi","en":"Dashboard stats"},"description":{"uz":"Sparkline bilan 4 ta KPI kartochka, AreaChart va hududlar bo'yicha ulush.","en":"Four KPI cards with sparklines, an AreaChart and a share-by-region list."},"dependencies":["@akhatmirzo/core","lucide-react","recharts"],"category":"dashboard"}, source: "'use client';\n\nimport { formatNumber } from '@akhatmirzo/core';\nimport { Badge, Button, Card, Progress, SegmentedControl } from '@akhatmirzo/ui';\nimport { AreaChart, Sparkline } from '@akhatmirzo/ui/charts';\nimport {\n  Download,\n  ReceiptText,\n  ShoppingBag,\n  TrendingDown,\n  TrendingUp,\n  Users,\n  Wallet,\n} from 'lucide-react';\nimport { useState, type ReactNode } from 'react';\n\ntype Period = 'week' | 'month' | 'year';\n\ninterface Kpi {\n  title: string;\n  icon: ReactNode;\n  value: string;\n  /** O'lchov birligi — qiymatdan kichikroq yoziladi */\n  unit?: string;\n  /** O'tgan davrga nisbatan o'zgarish, % */\n  delta: number;\n  /** `true` — o'sish yaxshi (tushum), `false` — kamayish yaxshi (qaytarishlar) */\n  upIsGood?: boolean;\n  trend: number[];\n}\n\ninterface Point {\n  label: string;\n  tushum: number;\n  xarajat: number;\n}\n\n/** KPI uchun: 234,4 mln */\nconst mlnShort = (v: number) => `${(v / 1_000_000).toFixed(1).replace('.', ',')} mln`;\n\n/** Qisqa ko'rinish: 63,1 mln so'm */\nconst mln = (v: number) => `${(v / 1_000_000).toFixed(1).replace('.', ',')} mln so'm`;\n\nconst SERIES: Record<Period, Point[]> = {\n  week: [\n    { label: 'Du', tushum: 8_400_000, xarajat: 5_100_000 },\n    { label: 'Se', tushum: 9_150_000, xarajat: 5_600_000 },\n    { label: 'Ch', tushum: 7_900_000, xarajat: 4_900_000 },\n    { label: 'Pa', tushum: 10_300_000, xarajat: 6_000_000 },\n    { label: 'Ju', tushum: 12_800_000, xarajat: 6_700_000 },\n    { label: 'Sh', tushum: 14_200_000, xarajat: 7_300_000 },\n    { label: 'Ya', tushum: 11_600_000, xarajat: 6_100_000 },\n  ],\n  month: [\n    { label: '1-hafta', tushum: 52_400_000, xarajat: 33_100_000 },\n    { label: '2-hafta', tushum: 58_900_000, xarajat: 35_400_000 },\n    { label: '3-hafta', tushum: 55_300_000, xarajat: 34_200_000 },\n    { label: '4-hafta', tushum: 67_800_000, xarajat: 38_900_000 },\n  ],\n  year: [\n    { label: 'Yan', tushum: 182_000_000, xarajat: 121_000_000 },\n    { label: 'Fev', tushum: 171_500_000, xarajat: 118_300_000 },\n    { label: 'Mar', tushum: 204_800_000, xarajat: 129_600_000 },\n    { label: 'Apr', tushum: 198_200_000, xarajat: 131_900_000 },\n    { label: 'May', tushum: 226_400_000, xarajat: 140_200_000 },\n    { label: 'Iyn', tushum: 241_700_000, xarajat: 146_800_000 },\n    { label: 'Iyl', tushum: 236_100_000, xarajat: 149_500_000 },\n    { label: 'Avg', tushum: 258_900_000, xarajat: 152_300_000 },\n    { label: 'Sen', tushum: 249_300_000, xarajat: 150_100_000 },\n    { label: 'Okt', tushum: 274_600_000, xarajat: 158_700_000 },\n  ],\n};\n\nconst KPIS: Record<Period, Kpi[]> = {\n  week: [\n    {\n      title: 'Tushum',\n      icon: <Wallet />,\n      value: mlnShort(74_350_000),\n      unit: \"so'm\",\n      delta: 12.4,\n      trend: [8, 9, 8, 10, 13, 14, 12],\n    },\n    {\n      title: 'Buyurtmalar',\n      icon: <ShoppingBag />,\n      value: formatNumber(1_284),\n      delta: 8.1,\n      trend: [150, 162, 148, 181, 205, 232, 206],\n    },\n    {\n      title: 'Yangi mijozlar',\n      icon: <Users />,\n      value: formatNumber(326),\n      delta: -3.2,\n      trend: [52, 49, 44, 47, 46, 43, 45],\n    },\n    {\n      title: \"O'rtacha chek\",\n      icon: <ReceiptText />,\n      value: formatNumber(57_900),\n      unit: \"so'm\",\n      delta: 4.6,\n      trend: [54, 55, 53, 56, 58, 57, 59],\n    },\n  ],\n  month: [\n    {\n      title: 'Tushum',\n      icon: <Wallet />,\n      value: mlnShort(234_400_000),\n      unit: \"so'm\",\n      delta: 9.8,\n      trend: [52, 59, 55, 68],\n    },\n    {\n      title: 'Buyurtmalar',\n      icon: <ShoppingBag />,\n      value: formatNumber(4_912),\n      delta: 6.3,\n      trend: [1120, 1215, 1180, 1397],\n    },\n    {\n      title: 'Yangi mijozlar',\n      icon: <Users />,\n      value: formatNumber(1_408),\n      delta: 2.1,\n      trend: [330, 352, 341, 385],\n    },\n    {\n      title: \"O'rtacha chek\",\n      icon: <ReceiptText />,\n      value: formatNumber(47_700),\n      unit: \"so'm\",\n      delta: -1.4,\n      trend: [49, 48, 47, 48],\n    },\n  ],\n  year: [\n    {\n      title: 'Tushum',\n      icon: <Wallet />,\n      value: mlnShort(2_243_500_000),\n      unit: \"so'm\",\n      delta: 23.7,\n      trend: [182, 171, 205, 198, 226, 242, 236, 259, 249, 275],\n    },\n    {\n      title: 'Buyurtmalar',\n      icon: <ShoppingBag />,\n      value: formatNumber(48_630),\n      delta: 18.2,\n      trend: [3.9, 3.7, 4.4, 4.3, 4.9, 5.1, 5.0, 5.4, 5.3, 5.8],\n    },\n    {\n      title: 'Yangi mijozlar',\n      icon: <Users />,\n      value: formatNumber(15_274),\n      delta: 31.5,\n      trend: [1.1, 1.2, 1.4, 1.3, 1.5, 1.6, 1.6, 1.7, 1.8, 1.9],\n    },\n    {\n      title: \"O'rtacha chek\",\n      icon: <ReceiptText />,\n      value: formatNumber(46_100),\n      unit: \"so'm\",\n      delta: 4.9,\n      trend: [44, 44, 45, 45, 46, 46, 46, 47, 47, 47],\n    },\n  ],\n};\n\nconst REGIONS = [\n  { name: 'Toshkent shahri', share: 46 },\n  { name: 'Samarqand', share: 18 },\n  { name: \"Farg'ona\", share: 14 },\n  { name: 'Buxoro', share: 12 },\n  { name: 'Boshqa viloyatlar', share: 10 },\n];\n\nconst PERIOD_LABEL: Record<Period, string> = {\n  week: \"o'tgan haftaga nisbatan\",\n  month: \"o'tgan oyga nisbatan\",\n  year: \"o'tgan yilga nisbatan\",\n};\n\nexport default function DashboardStatsBlock() {\n  const [period, setPeriod] = useState<Period>('month');\n\n  return (\n    <section className=\"@container w-full bg-background font-sans text-text\">\n      <div className=\"flex flex-col gap-6 p-4 @3xl:p-8\">\n        <div className=\"flex flex-col gap-4 @3xl:flex-row @3xl:items-end @3xl:justify-between\">\n          <div className=\"flex flex-col gap-1\">\n            <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Umumiy ko&apos;rinish</h2>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Chorsu Market — barcha filiallar bo&apos;yicha savdo ko&apos;rsatkichlari\n            </p>\n          </div>\n          <div className=\"flex flex-wrap items-center gap-2\">\n            <SegmentedControl\n              size=\"sm\"\n              value={period}\n              onValueChange={(value) => setPeriod(value as Period)}\n              aria-label=\"Davr\"\n            >\n              <SegmentedControl.Item value=\"week\">7 kun</SegmentedControl.Item>\n              <SegmentedControl.Item value=\"month\">30 kun</SegmentedControl.Item>\n              <SegmentedControl.Item value=\"year\">Yil</SegmentedControl.Item>\n            </SegmentedControl>\n            <Button size=\"sm\" variant=\"outline\" leftIcon={<Download />}>\n              Eksport\n            </Button>\n          </div>\n        </div>\n\n        <div className=\"grid gap-4 @xl:grid-cols-2 @5xl:grid-cols-4\">\n          {KPIS[period].map((kpi) => {\n            const good = kpi.upIsGood === false ? kpi.delta < 0 : kpi.delta >= 0;\n            return (\n              <Card key={kpi.title} padding=\"sm\" className=\"gap-3\">\n                <div className=\"flex items-center justify-between gap-2\">\n                  <span className=\"text-sm font-medium text-text-muted\">{kpi.title}</span>\n                  <span\n                    className=\"grid size-8 place-items-center rounded-lg bg-primary-soft text-primary-soft-foreground [&_svg]:size-4\"\n                    aria-hidden=\"true\"\n                  >\n                    {kpi.icon}\n                  </span>\n                </div>\n                <div className=\"flex items-end justify-between gap-3\">\n                  <div className=\"flex min-w-0 flex-col gap-1.5\">\n                    <span className=\"truncate text-2xl font-bold tracking-tight tabular-nums\">\n                      {kpi.value}\n                      {kpi.unit && (\n                        <span className=\"ml-1 text-sm font-medium text-text-muted\">{kpi.unit}</span>\n                      )}\n                    </span>\n                    <span className=\"flex flex-wrap items-center gap-1.5 text-xs text-text-muted\">\n                      <Badge size=\"sm\" color={good ? 'success' : 'danger'}>\n                        {kpi.delta >= 0 ? (\n                          <TrendingUp className=\"size-3\" aria-hidden=\"true\" />\n                        ) : (\n                          <TrendingDown className=\"size-3\" aria-hidden=\"true\" />\n                        )}\n                        {kpi.delta > 0 ? '+' : ''}\n                        {String(kpi.delta).replace('.', ',')}%\n                      </Badge>\n                      {PERIOD_LABEL[period]}\n                    </span>\n                  </div>\n                  {/* Qiymat matn bilan berilgan — grafik faqat bezak */}\n                  <Sparkline\n                    aria-hidden\n                    data={kpi.trend}\n                    color={good ? 'success' : 'danger'}\n                    className=\"w-20 shrink-0\"\n                  />\n                </div>\n              </Card>\n            );\n          })}\n        </div>\n\n        <div className=\"grid gap-4 @5xl:grid-cols-[minmax(0,2fr)_minmax(0,1fr)]\">\n          <Card className=\"gap-4\">\n            <div className=\"flex flex-col gap-1\">\n              <h3 className=\"m-0 text-base font-semibold\">Tushum va xarajat</h3>\n              <p className=\"m-0 text-sm text-text-muted\">\n                So&apos;mda, tanlangan davr bo&apos;yicha\n              </p>\n            </div>\n            <AreaChart\n              aria-label=\"Tushum va xarajat dinamikasi\"\n              className=\"w-full\"\n              data={SERIES[period]}\n              index=\"label\"\n              series={[\n                { key: 'tushum', label: 'Tushum' },\n                { key: 'xarajat', label: 'Xarajat', color: 'amber' },\n              ]}\n              valueFormat={mln}\n              height={280}\n            />\n          </Card>\n\n          <Card className=\"gap-5\">\n            <div className=\"flex flex-col gap-1\">\n              <h3 className=\"m-0 text-base font-semibold\">Hududlar bo&apos;yicha</h3>\n              <p className=\"m-0 text-sm text-text-muted\">Buyurtmalar ulushi</p>\n            </div>\n            <ul className=\"m-0 flex list-none flex-col gap-4 p-0\">\n              {REGIONS.map((region) => (\n                <li key={region.name}>\n                  <Progress size=\"sm\" value={region.share} label={region.name} showValue />\n                </li>\n              ))}\n            </ul>\n          </Card>\n        </div>\n      </div>\n    </section>\n  );\n}\n" },
  "data-table-page": { component: Block3, file: "data-table-page/data-table-page.tsx", meta: {"title":{"uz":"Jadval sahifasi","en":"Data table page"},"description":{"uz":"Sarlavha, qidiruv va filtrlar, DataTable, Pagination va bo'sh natija holati.","en":"Page header, search and filters, DataTable, Pagination and an empty result state."},"dependencies":["@akhatmirzo/core","lucide-react"],"category":"data"}, source: "'use client';\n\nimport { formatDate, formatMoney, formatPhone } from '@akhatmirzo/core';\nimport {\n  Avatar,\n  Badge,\n  Button,\n  DataTable,\n  DropdownMenu,\n  EmptyState,\n  IconButton,\n  Input,\n  Pagination,\n  PaginationInfo,\n  Select,\n  toast,\n  type BadgeColor,\n  type DataTableColumn,\n} from '@akhatmirzo/ui';\nimport {\n  Ban,\n  Download,\n  Ellipsis,\n  Eye,\n  FilterX,\n  Plus,\n  Printer,\n  Search,\n  SearchX,\n} from 'lucide-react';\nimport { useMemo, useState } from 'react';\n\ntype Status = 'new' | 'packing' | 'shipping' | 'delivered' | 'cancelled';\n\ninterface Order {\n  id: number;\n  customer: string;\n  phone: string;\n  region: string;\n  date: Date;\n  status: Status;\n  total: number;\n}\n\nconst STATUS: Record<Status, { label: string; color: BadgeColor }> = {\n  new: { label: 'Yangi', color: 'info' },\n  packing: { label: \"Yig'ilmoqda\", color: 'warning' },\n  shipping: { label: \"Yo'lda\", color: 'primary' },\n  delivered: { label: 'Yetkazildi', color: 'success' },\n  cancelled: { label: 'Bekor qilindi', color: 'danger' },\n};\n\nconst CUSTOMERS = [\n  'Dilnoza Yusupova',\n  'Otabek Qodirov',\n  'Malika Rahimova',\n  'Jasur Karimov',\n  'Nodira Saidova',\n  'Rustam Xolmatov',\n  'Shahnoza Ergasheva',\n  'Sardor Aliyev',\n];\nconst REGIONS = ['Toshkent', 'Samarqand', 'Buxoro', \"Farg'ona\", 'Andijon', 'Namangan'];\nconst OPERATORS = ['90', '91', '93', '94', '97', '99', '88', '33'];\nconst STATUSES: Status[] = ['delivered', 'shipping', 'new', 'delivered', 'packing', 'cancelled'];\n\nconst ORDERS: Order[] = Array.from({ length: 46 }, (_, i) => ({\n  id: 10482 - i,\n  customer: CUSTOMERS[(i * 5) % CUSTOMERS.length]!,\n  phone: `${OPERATORS[i % OPERATORS.length]}${String(1_234_567 + i * 104_729).slice(-7)}`,\n  region: REGIONS[(i * 3 + (i >> 2)) % REGIONS.length]!,\n  date: new Date(2026, 9, 22 - Math.floor(i / 3)),\n  status: STATUSES[(i * 7) % STATUSES.length]!,\n  total: 85_000 + ((i * 271_828) % 4_200_000),\n}));\n\nconst PAGE_SIZE = 8;\n\nconst columns: DataTableColumn<Order>[] = [\n  { key: 'id', header: '№', width: 96, cell: (o) => <span className=\"font-medium\">#{o.id}</span> },\n  {\n    key: 'customer',\n    header: 'Mijoz',\n    cell: (o) => (\n      <span className=\"flex items-center gap-2.5\">\n        <Avatar name={o.customer} size=\"sm\" />\n        <span className=\"flex min-w-0 flex-col\">\n          <span className=\"truncate font-medium\">{o.customer}</span>\n          <span className=\"text-xs text-text-muted tabular-nums\">{formatPhone(o.phone)}</span>\n        </span>\n      </span>\n    ),\n  },\n  { key: 'region', header: 'Hudud' },\n  { key: 'date', header: 'Sana', cell: (o) => formatDate(o.date) },\n  {\n    key: 'status',\n    header: 'Holat',\n    cell: (o) => (\n      <Badge color={STATUS[o.status].color} dot>\n        {STATUS[o.status].label}\n      </Badge>\n    ),\n  },\n  { key: 'total', header: 'Summa', numeric: true, cell: (o) => formatMoney(o.total) },\n];\n\nexport default function DataTablePageBlock() {\n  const [query, setQuery] = useState('');\n  const [status, setStatus] = useState<Status | 'all'>('all');\n  const [region, setRegion] = useState('all');\n  const [page, setPage] = useState(1);\n\n  const filtered = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return ORDERS.filter(\n      (o) =>\n        (status === 'all' || o.status === status) &&\n        (region === 'all' || o.region === region) &&\n        (!q || o.customer.toLowerCase().includes(q) || String(o.id).includes(q)),\n    );\n  }, [query, status, region]);\n\n  const rows = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);\n  const hasFilters = query !== '' || status !== 'all' || region !== 'all';\n\n  // Filtr o'zgarsa — birinchi sahifaga qaytamiz\n  const search = (value: string) => {\n    setQuery(value);\n    setPage(1);\n  };\n\n  const reset = () => {\n    setQuery('');\n    setStatus('all');\n    setRegion('all');\n    setPage(1);\n  };\n\n  return (\n    <section className=\"@container w-full bg-background font-sans text-text\">\n      <div className=\"flex flex-col gap-6 p-4 @3xl:p-8\">\n        <div className=\"flex flex-col gap-4 @2xl:flex-row @2xl:items-end @2xl:justify-between\">\n          <div className=\"flex flex-col gap-1\">\n            <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Buyurtmalar</h2>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Oxirgi 30 kundagi {ORDERS.length} ta buyurtma — holat va hudud bo&apos;yicha saralang\n            </p>\n          </div>\n          <div className=\"flex gap-2\">\n            <Button\n              variant=\"outline\"\n              leftIcon={<Download />}\n              onClick={() => toast(`${filtered.length} ta buyurtma Excel'ga eksport qilindi`)}\n            >\n              Eksport\n            </Button>\n            <Button variant=\"primary\" leftIcon={<Plus />}>\n              Yangi buyurtma\n            </Button>\n          </div>\n        </div>\n\n        <div className=\"grid gap-3 @2xl:grid-cols-[minmax(0,1fr)_200px_200px] @4xl:grid-cols-[minmax(0,1fr)_220px_220px_auto]\">\n          <Input\n            aria-label=\"Qidirish\"\n            placeholder=\"Mijoz yoki buyurtma raqami\"\n            leftIcon={<Search />}\n            clearable\n            value={query}\n            onChange={(e) => search(e.target.value)}\n            onClear={() => search('')}\n          />\n          <Select\n            aria-label=\"Holat\"\n            value={status}\n            onValueChange={(value) => {\n              setStatus(value as Status | 'all');\n              setPage(1);\n            }}\n          >\n            <Select.Item value=\"all\">Barcha holatlar</Select.Item>\n            {(Object.keys(STATUS) as Status[]).map((key) => (\n              <Select.Item key={key} value={key}>\n                {STATUS[key].label}\n              </Select.Item>\n            ))}\n          </Select>\n          <Select\n            aria-label=\"Hudud\"\n            value={region}\n            onValueChange={(value) => {\n              setRegion(value);\n              setPage(1);\n            }}\n          >\n            <Select.Item value=\"all\">Barcha hududlar</Select.Item>\n            {REGIONS.map((name) => (\n              <Select.Item key={name} value={name}>\n                {name}\n              </Select.Item>\n            ))}\n          </Select>\n          {hasFilters && (\n            <Button variant=\"ghost\" leftIcon={<FilterX />} onClick={reset}>\n              Tozalash\n            </Button>\n          )}\n        </div>\n\n        {filtered.length === 0 ? (\n          <div className=\"rounded-xl border border-dashed border-border\">\n            <EmptyState\n              icon={<SearchX />}\n              title=\"Hech narsa topilmadi\"\n              description=\"Tanlangan filtrlarga mos buyurtma yo'q. Qidiruv so'zini yoki filtrlarni o'zgartirib ko'ring.\"\n              action={\n                <Button variant=\"outline\" leftIcon={<FilterX />} onClick={reset}>\n                  Filtrlarni tozalash\n                </Button>\n              }\n            />\n          </div>\n        ) : (\n          <div className=\"flex flex-col gap-3\">\n            <DataTable\n              label=\"Buyurtmalar\"\n              data={rows}\n              columns={columns}\n              getRowId={(o) => String(o.id)}\n              className=\"w-full\"\n              rowActions={(o) => (\n                <DropdownMenu>\n                  <DropdownMenu.Trigger asChild>\n                    <IconButton variant=\"ghost\" size=\"sm\" aria-label={`#${o.id} amallari`}>\n                      <Ellipsis />\n                    </IconButton>\n                  </DropdownMenu.Trigger>\n                  <DropdownMenu.Content align=\"end\">\n                    <DropdownMenu.Item icon={<Eye />}>Batafsil</DropdownMenu.Item>\n                    <DropdownMenu.Item\n                      icon={<Printer />}\n                      onSelect={() => toast(`#${o.id} uchun chek chop etilmoqda`)}\n                    >\n                      Chek chiqarish\n                    </DropdownMenu.Item>\n                    <DropdownMenu.Separator />\n                    <DropdownMenu.Item\n                      icon={<Ban />}\n                      variant=\"danger\"\n                      disabled={o.status === 'delivered' || o.status === 'cancelled'}\n                      onSelect={() => toast.error(`#${o.id} bekor qilindi`)}\n                    >\n                      Bekor qilish\n                    </DropdownMenu.Item>\n                  </DropdownMenu.Content>\n                </DropdownMenu>\n              )}\n            />\n            <div className=\"flex flex-col items-center gap-3 @2xl:flex-row @2xl:justify-between\">\n              <PaginationInfo page={page} pageSize={PAGE_SIZE} total={filtered.length} />\n              <Pagination\n                page={page}\n                onPageChange={setPage}\n                total={filtered.length}\n                pageSize={PAGE_SIZE}\n                size=\"sm\"\n              />\n            </div>\n          </div>\n        )}\n      </div>\n    </section>\n  );\n}\n" },
  "login": { component: Block4, file: "login/login.tsx", meta: {"title":{"uz":"Kirish","en":"Login"},"description":{"uz":"Telefon yoki email va parol bilan kirish: \"Esda qolsin\", Google tugmasi va xato holati.","en":"Sign in with phone or email and password: remember me, a Google button and an error state."},"dependencies":["@akhatmirzo/core","lucide-react"],"category":"auth"}, source: "'use client';\n\nimport { isValidEmail, parsePhone } from '@akhatmirzo/core';\nimport {\n  Alert,\n  Button,\n  Checkbox,\n  Divider,\n  Field,\n  Input,\n  PhoneInput,\n  SegmentedControl,\n  toast,\n} from '@akhatmirzo/ui';\nimport { LogIn, Mail, Phone, ShieldCheck, Store } from 'lucide-react';\nimport { useState, type FormEvent } from 'react';\n\ntype Method = 'phone' | 'email';\n\ninterface Errors {\n  login?: string;\n  password?: string;\n}\n\n/** Google belgisi (bir rangli — tugma matni rangini oladi) */\nfunction GoogleMark() {\n  return (\n    <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" fill=\"currentColor\">\n      <path d=\"M21.35 11.1H12v2.98h5.35c-.23 1.43-1.66 4.2-5.35 4.2-3.22 0-5.85-2.67-5.85-5.96S8.78 6.36 12 6.36c1.83 0 3.06.78 3.76 1.45l2.57-2.47C16.68 3.8 14.55 2.86 12 2.86 6.98 2.86 2.92 6.92 2.92 12S6.98 21.14 12 21.14c5.27 0 8.77-3.7 8.77-8.92 0-.6-.07-1.06-.15-1.52Z\" />\n    </svg>\n  );\n}\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function LoginBlock() {\n  const [method, setMethod] = useState<Method>('phone');\n  const [phone, setPhone] = useState('');\n  const [email, setEmail] = useState('');\n  const [password, setPassword] = useState('');\n  const [remember, setRemember] = useState(true);\n  const [errors, setErrors] = useState<Errors>({});\n  const [serverError, setServerError] = useState('');\n  const [loading, setLoading] = useState(false);\n\n  const validate = (): Errors => {\n    const next: Errors = {};\n    if (method === 'phone') {\n      const parsed = parsePhone(phone);\n      if (!phone) next.login = 'Telefon raqamini kiriting';\n      else if (parsed.digits.length < 9) next.login = \"Raqamni to'liq kiriting\";\n      else if (!parsed.valid) next.login = \"Operator kodi noto'g'ri\";\n    } else if (!email.trim()) next.login = 'Email manzilini kiriting';\n    else if (!isValidEmail(email.trim())) next.login = \"Email noto'g'ri, masalan: ism@misol.uz\";\n    if (!password) next.password = 'Parolni kiriting';\n    return next;\n  };\n\n  const onSubmit = async (event: FormEvent) => {\n    event.preventDefault();\n    const found = validate();\n    setErrors(found);\n    setServerError('');\n    if (found.login || found.password) return;\n\n    setLoading(true);\n    // Haqiqiy ilovada — API so'rovi. Bu yerda: 8 belgidan qisqa parol \"noto'g'ri\" hisoblanadi\n    await wait(900);\n    setLoading(false);\n    if (password.length < 8) {\n      setServerError(\"Login yoki parol noto'g'ri. Qayta urinib ko'ring yoki parolni tiklang.\");\n      setPassword('');\n      return;\n    }\n    toast.success('Xush kelibsiz!', { description: 'Hisobingizga muvaffaqiyatli kirdingiz.' });\n  };\n\n  return (\n    <div className=\"@container w-full bg-background font-sans text-text\">\n      <div className=\"grid min-h-[640px] @3xl:grid-cols-[minmax(0,5fr)_minmax(0,6fr)]\">\n        {/* Brend paneli — faqat keng ekranda */}\n        <aside className=\"relative hidden flex-col justify-between overflow-hidden bg-primary p-10 text-primary-foreground @3xl:flex\">\n          <span\n            aria-hidden=\"true\"\n            className=\"absolute -top-24 -right-24 size-72 rounded-full bg-primary-foreground/10\"\n          />\n          <span\n            aria-hidden=\"true\"\n            className=\"absolute -bottom-32 -left-16 size-80 rounded-full bg-primary-foreground/5\"\n          />\n          <div className=\"relative flex items-center gap-2.5\">\n            <span className=\"grid size-10 place-items-center rounded-xl bg-primary-foreground/15\">\n              <Store className=\"size-5\" aria-hidden=\"true\" />\n            </span>\n            <span className=\"text-lg font-bold\">Chorsu Market</span>\n          </div>\n          <div className=\"relative flex flex-col gap-4\">\n            <p className=\"m-0 text-3xl leading-tight font-bold\">\n              Do&apos;koningizni bitta oynadan boshqaring\n            </p>\n            <p className=\"m-0 max-w-sm text-primary-foreground/80\">\n              Buyurtmalar, ombor va to&apos;lovlar — Toshkentdan Nukusgacha 12 000 dan ortiq\n              sotuvchi ishonadi.\n            </p>\n          </div>\n          <div className=\"relative flex items-center gap-2 text-sm text-primary-foreground/80\">\n            <ShieldCheck className=\"size-4\" aria-hidden=\"true\" />\n            Ma&apos;lumotlaringiz shifrlangan holda saqlanadi\n          </div>\n        </aside>\n\n        <div className=\"flex items-center justify-center px-4 py-10 @md:px-8\">\n          <form noValidate onSubmit={onSubmit} className=\"flex w-full max-w-sm flex-col gap-5\">\n            <div className=\"flex flex-col gap-1.5\">\n              <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Hisobga kirish</h2>\n              <p className=\"m-0 text-sm text-text-muted\">\n                Hisobingiz yo&apos;qmi?{' '}\n                <a href=\"#register\" className=\"font-medium text-link hover:underline\">\n                  Ro&apos;yxatdan o&apos;ting\n                </a>\n              </p>\n            </div>\n\n            <SegmentedControl\n              fullWidth\n              value={method}\n              onValueChange={(value) => {\n                setMethod(value as Method);\n                setErrors({});\n              }}\n              aria-label=\"Kirish usuli\"\n            >\n              <SegmentedControl.Item value=\"phone\" icon={<Phone />}>\n                Telefon\n              </SegmentedControl.Item>\n              <SegmentedControl.Item value=\"email\" icon={<Mail />}>\n                Email\n              </SegmentedControl.Item>\n            </SegmentedControl>\n\n            {serverError && (\n              <Alert color=\"danger\" title=\"Kirib bo'lmadi\">\n                {serverError}\n              </Alert>\n            )}\n\n            {method === 'phone' ? (\n              <Field label=\"Telefon raqami\" error={errors.login} required>\n                <PhoneInput value={phone} onValueChange={setPhone} autoComplete=\"tel\" />\n              </Field>\n            ) : (\n              <Field label=\"Email\" error={errors.login} required>\n                <Input\n                  type=\"email\"\n                  value={email}\n                  onChange={(e) => setEmail(e.target.value)}\n                  placeholder=\"ism@misol.uz\"\n                  autoComplete=\"email\"\n                />\n              </Field>\n            )}\n\n            <Field label=\"Parol\" error={errors.password} required>\n              <Input\n                type=\"password\"\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                autoComplete=\"current-password\"\n              />\n            </Field>\n\n            <div className=\"flex flex-wrap items-center justify-between gap-2\">\n              <Checkbox\n                label=\"Esda qolsin\"\n                checked={remember}\n                onCheckedChange={setRemember}\n                size=\"sm\"\n              />\n              <a href=\"#forgot\" className=\"text-sm font-medium text-link hover:underline\">\n                Parolni unutdingizmi?\n              </a>\n            </div>\n\n            <Button\n              type=\"submit\"\n              variant=\"primary\"\n              fullWidth\n              loading={loading}\n              leftIcon={<LogIn />}\n            >\n              Kirish\n            </Button>\n\n            <Divider label=\"yoki\" />\n\n            <Button\n              type=\"button\"\n              variant=\"outline\"\n              fullWidth\n              leftIcon={<GoogleMark />}\n              onClick={() =>\n                toast('Google orqali kirish', { description: 'OAuth oynasi ochiladi' })\n              }\n            >\n              Google bilan kirish\n            </Button>\n\n            <p className=\"m-0 text-center text-xs text-text-muted\">\n              Kirish orqali siz{' '}\n              <a href=\"#terms\" className=\"underline underline-offset-2 hover:text-text\">\n                foydalanish shartlari\n              </a>\n              ga rozilik bildirasiz.\n            </p>\n          </form>\n        </div>\n      </div>\n    </div>\n  );\n}\n" },
  "otp-verify": { component: Block5, file: "otp-verify/otp-verify.tsx", meta: {"title":{"uz":"SMS kodni tasdiqlash","en":"OTP verification"},"description":{"uz":"OtpInput va useCountdown bilan 6 xonali SMS kodni tasdiqlash, qayta yuborish taymeri.","en":"Verify a 6-digit SMS code with OtpInput and a useCountdown resend timer."},"dependencies":["@akhatmirzo/hooks","lucide-react"],"category":"auth"}, source: "'use client';\n\nimport { useCountdown } from '@akhatmirzo/hooks';\nimport { Button, Card, Field, OtpInput, toast } from '@akhatmirzo/ui';\nimport { ArrowLeft, CircleCheck, MessageSquareText, RotateCw } from 'lucide-react';\nimport { useState } from 'react';\n\nconst PHONE_MASKED = '+998 90 *** ** 67';\n/** Sinov uchun to'g'ri kod — haqiqiy ilovada kod serverda tekshiriladi */\nconst DEMO_CODE = '246810';\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function OtpVerifyBlock() {\n  const [code, setCode] = useState('');\n  const [error, setError] = useState('');\n  const [checking, setChecking] = useState(false);\n  const [verified, setVerified] = useState(false);\n  const [attempts, setAttempts] = useState(3);\n  const { formatted, isRunning, restart } = useCountdown(59);\n\n  const verify = async (value: string) => {\n    setChecking(true);\n    setError('');\n    await wait(800);\n    setChecking(false);\n    if (value === DEMO_CODE) {\n      setVerified(true);\n      return;\n    }\n    const left = attempts - 1;\n    setAttempts(left);\n    setCode('');\n    setError(\n      left > 0\n        ? `Kod noto'g'ri. Yana ${left} ta urinish qoldi.`\n        : 'Urinishlar tugadi. Yangi kod oling.',\n    );\n  };\n\n  const resend = () => {\n    // Haqiqiy ilovada — SMS yuborish so'rovi\n    setCode('');\n    setError('');\n    setAttempts(3);\n    restart();\n    toast(`Yangi kod ${PHONE_MASKED} raqamiga yuborildi`);\n  };\n\n  return (\n    <div className=\"@container w-full bg-surface-muted font-sans text-text\">\n      <div className=\"flex min-h-[600px] items-center justify-center px-4 py-10\">\n        <Card className=\"w-full max-w-md items-center text-center @md:p-8\">\n          {verified ? (\n            <div className=\"flex flex-col items-center gap-4 py-6\" role=\"status\">\n              <span className=\"grid size-16 place-items-center rounded-full bg-success-soft text-success\">\n                <CircleCheck className=\"size-8\" aria-hidden=\"true\" />\n              </span>\n              <div className=\"flex flex-col gap-1.5\">\n                <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Raqam tasdiqlandi</h2>\n                <p className=\"m-0 text-sm text-text-muted\">\n                  {PHONE_MASKED} hisobingizga bog&apos;landi.\n                </p>\n              </div>\n              <Button variant=\"primary\" fullWidth>\n                Davom etish\n              </Button>\n            </div>\n          ) : (\n            <div className=\"flex w-full flex-col items-center gap-6\">\n              <span className=\"grid size-14 place-items-center rounded-2xl bg-primary-soft text-primary-soft-foreground\">\n                <MessageSquareText className=\"size-7\" aria-hidden=\"true\" />\n              </span>\n\n              <div className=\"flex flex-col gap-1.5\">\n                <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Telefonni tasdiqlang</h2>\n                <p className=\"m-0 text-sm text-text-muted\">\n                  <span className=\"font-medium whitespace-nowrap text-text\">{PHONE_MASKED}</span>{' '}\n                  raqamiga 6 xonali kod yubordik.\n                </p>\n              </div>\n\n              <form\n                noValidate\n                onSubmit={(event) => {\n                  event.preventDefault();\n                  if (code.length === 6 && !checking) void verify(code);\n                }}\n                className=\"flex w-full flex-col items-center gap-6\"\n              >\n                <Field\n                  label=\"Tasdiqlash kodi\"\n                  description={`Sinov kodi: ${DEMO_CODE}`}\n                  error={error}\n                  className=\"items-center\"\n                >\n                  <OtpInput\n                    length={6}\n                    groupSize={3}\n                    value={code}\n                    onValueChange={(value) => {\n                      setCode(value);\n                      if (error) setError('');\n                    }}\n                    onComplete={verify}\n                    invalid={Boolean(error)}\n                    disabled={checking || attempts === 0}\n                  />\n                </Field>\n\n                <Button\n                  type=\"submit\"\n                  variant=\"primary\"\n                  fullWidth\n                  loading={checking}\n                  disabled={code.length < 6 || attempts === 0}\n                >\n                  Tasdiqlash\n                </Button>\n              </form>\n\n              <div className=\"flex w-full flex-col items-center gap-1 border-t border-border pt-4 text-sm\">\n                <span className=\"text-text-muted\">Kod kelmadimi?</span>\n                <Button\n                  variant=\"ghost\"\n                  size=\"sm\"\n                  disabled={isRunning}\n                  onClick={resend}\n                  leftIcon={<RotateCw />}\n                >\n                  {isRunning ? (\n                    <>\n                      Qayta yuborish <span className=\"tabular-nums\">({formatted})</span>\n                    </>\n                  ) : (\n                    'Kodni qayta yuborish'\n                  )}\n                </Button>\n              </div>\n\n              <a\n                href=\"#change-phone\"\n                className=\"inline-flex items-center gap-1.5 text-sm font-medium text-link hover:underline\"\n              >\n                <ArrowLeft className=\"size-4\" aria-hidden=\"true\" />\n                Raqamni o&apos;zgartirish\n              </a>\n            </div>\n          )}\n        </Card>\n      </div>\n    </div>\n  );\n}\n" },
  "pricing": { component: Block6, file: "pricing/pricing.tsx", meta: {"title":{"uz":"Tariflar","en":"Pricing"},"description":{"uz":"Uchta tarif kartochkasi, oylik/yillik almashtirgich va so'mdagi narxlar.","en":"Three pricing cards with a monthly/yearly switch and prices in so'm."},"dependencies":["@akhatmirzo/core","lucide-react"],"category":"marketing"}, source: "'use client';\n\nimport { formatMoney } from '@akhatmirzo/core';\nimport { Badge, Button, Card, SegmentedControl, cn } from '@akhatmirzo/ui';\nimport { Building2, Check, Rocket, Sparkles } from 'lucide-react';\nimport { useState, type ReactNode } from 'react';\n\ntype Period = 'month' | 'year';\n\ninterface Plan {\n  id: string;\n  name: string;\n  icon: ReactNode;\n  description: string;\n  /** Oylik narx, so'mda (0 — bepul, null — kelishiladi) */\n  monthly: number | null;\n  features: string[];\n  cta: string;\n  popular?: boolean;\n}\n\n/** Yillik to'lovda chegirma */\nconst YEARLY_DISCOUNT = 0.2;\n\nconst plans: Plan[] = [\n  {\n    id: 'start',\n    name: \"Boshlang'ich\",\n    icon: <Sparkles />,\n    description: \"Yangi ochilgan kichik do'kon uchun\",\n    monthly: 0,\n    features: ['50 tagacha mahsulot', '1 ta xodim', \"Click va Payme orqali to'lov\", 'Email yordam'],\n    cta: 'Bepul boshlash',\n  },\n  {\n    id: 'business',\n    name: 'Biznes',\n    icon: <Rocket />,\n    description: \"O'sib borayotgan savdo uchun hamma narsa\",\n    monthly: 349_000,\n    features: [\n      'Cheksiz mahsulot',\n      '10 tagacha xodim',\n      'Uzcard, Humo va Visa',\n      'Ombor va yetkazib berish',\n      'Telegram bot orqali bildirishnoma',\n      'Ustuvor yordam 24/7',\n    ],\n    cta: \"Biznesga o'tish\",\n    popular: true,\n  },\n  {\n    id: 'enterprise',\n    name: 'Korporativ',\n    icon: <Building2 />,\n    description: \"Filiallar tarmog'i va katta jamoalar\",\n    monthly: null,\n    features: [\n      'Biznesdagi hamma imkoniyat',\n      'Cheksiz xodim va filial',\n      '1C va soliq integratsiyasi',\n      'Shaxsiy menejer',\n      'SLA 99,9%',\n    ],\n    cta: \"Bog'lanish\",\n  },\n];\n\nexport default function PricingBlock() {\n  const [period, setPeriod] = useState<Period>('month');\n\n  const priceOf = (plan: Plan) => {\n    if (plan.monthly == null || plan.monthly === 0) return plan.monthly;\n    // Yillikda ham oyiga narx ko'rsatiladi; 1 000 so'mgacha yaxlitlanadi\n    return period === 'year'\n      ? Math.round((plan.monthly * (1 - YEARLY_DISCOUNT)) / 1000) * 1000\n      : plan.monthly;\n  };\n\n  return (\n    <section className=\"@container w-full bg-background font-sans text-text\">\n      <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-10 px-4 py-14 @3xl:px-8 @3xl:py-20\">\n        <div className=\"flex max-w-2xl flex-col items-center gap-3 text-center\">\n          <Badge color=\"primary\">Tariflar</Badge>\n          <h2 className=\"m-0 text-3xl font-bold tracking-tight @3xl:text-4xl\">\n            Biznesingizga mos tarifni tanlang\n          </h2>\n          <p className=\"m-0 text-text-muted\">\n            Istalgan vaqtda tarifni almashtiring yoki bekor qiling. Narxlar QQS bilan, so&apos;mda.\n          </p>\n        </div>\n\n        <div className=\"flex items-center gap-3\">\n          <SegmentedControl\n            value={period}\n            onValueChange={(value) => setPeriod(value as Period)}\n            aria-label=\"To'lov davri\"\n          >\n            <SegmentedControl.Item value=\"month\">Oylik</SegmentedControl.Item>\n            <SegmentedControl.Item value=\"year\">Yillik</SegmentedControl.Item>\n          </SegmentedControl>\n          <Badge color=\"success\" variant={period === 'year' ? 'solid' : 'soft'}>\n            −{YEARLY_DISCOUNT * 100}%\n          </Badge>\n        </div>\n\n        <div className=\"grid w-full max-w-md gap-6 @3xl:max-w-none @3xl:grid-cols-3 @3xl:items-stretch\">\n          {plans.map((plan) => {\n            const price = priceOf(plan);\n            return (\n              <Card\n                key={plan.id}\n                className={cn(\n                  'relative gap-6',\n                  plan.popular &&\n                    'border-primary shadow-lg ring-1 ring-primary @3xl:-my-3 @3xl:py-9',\n                )}\n              >\n                {plan.popular && (\n                  <Badge variant=\"solid\" color=\"primary\" className=\"absolute -top-3 left-6\">\n                    Eng ommabop\n                  </Badge>\n                )}\n\n                <div className=\"flex flex-col gap-3\">\n                  <span\n                    className={cn(\n                      'grid size-10 place-items-center rounded-xl [&_svg]:size-5',\n                      plan.popular\n                        ? 'bg-primary text-primary-foreground'\n                        : 'bg-primary-soft text-primary-soft-foreground',\n                    )}\n                    aria-hidden=\"true\"\n                  >\n                    {plan.icon}\n                  </span>\n                  <div>\n                    <h3 className=\"m-0 text-lg font-semibold\">{plan.name}</h3>\n                    <p className=\"m-0 text-sm text-text-muted\">{plan.description}</p>\n                  </div>\n                </div>\n\n                <div className=\"flex min-h-16 flex-col justify-end\">\n                  {price == null ? (\n                    <p className=\"m-0 text-3xl font-bold tracking-tight\">Kelishiladi</p>\n                  ) : price === 0 ? (\n                    <p className=\"m-0 text-3xl font-bold tracking-tight\">Bepul</p>\n                  ) : (\n                    <>\n                      <p className=\"m-0 flex flex-wrap items-baseline gap-x-1.5\">\n                        <span className=\"text-3xl font-bold tracking-tight tabular-nums\">\n                          {formatMoney(price, { currency: false })}\n                        </span>\n                        <span className=\"text-sm text-text-muted\">so&apos;m / oy</span>\n                      </p>\n                      <p className=\"m-0 h-5 text-xs text-text-muted tabular-nums\">\n                        {period === 'year' && plan.monthly\n                          ? `Yiliga ${formatMoney(price * 12)} — ${formatMoney((plan.monthly - price) * 12)} tejaysiz`\n                          : ''}\n                      </p>\n                    </>\n                  )}\n                </div>\n\n                <Button variant={plan.popular ? 'primary' : 'outline'} fullWidth>\n                  {plan.cta}\n                </Button>\n\n                <ul className=\"m-0 flex list-none flex-col gap-2.5 border-t border-border p-0 pt-6\">\n                  {plan.features.map((feature) => (\n                    <li key={feature} className=\"flex items-start gap-2.5 text-sm\">\n                      <Check className=\"mt-0.5 size-4 shrink-0 text-success\" aria-hidden=\"true\" />\n                      {feature}\n                    </li>\n                  ))}\n                </ul>\n              </Card>\n            );\n          })}\n        </div>\n      </div>\n    </section>\n  );\n}\n" },
  "register": { component: Block7, file: "register/register.tsx", meta: {"title":{"uz":"Ro'yxatdan o'tish","en":"Register"},"description":{"uz":"Ism, +998 telefon, parol kuchi ko'rsatkichi va shartlarga rozilik bilan ro'yxatdan o'tish formasi.","en":"Sign-up form with name, +998 phone, a password strength meter and terms consent."},"dependencies":["@akhatmirzo/core","lucide-react"],"category":"auth"}, source: "'use client';\n\nimport { parsePhone, passwordStrength, type PasswordScore } from '@akhatmirzo/core';\nimport {\n  Button,\n  Card,\n  Checkbox,\n  Field,\n  Input,\n  PhoneInput,\n  Progress,\n  toast,\n  type ProgressColor,\n} from '@akhatmirzo/ui';\nimport { Check, Store, UserPlus, X } from 'lucide-react';\nimport { useState, type FormEvent } from 'react';\n\ninterface Errors {\n  firstName?: string;\n  lastName?: string;\n  phone?: string;\n  password?: string;\n  terms?: string;\n}\n\nconst SCORE_COLOR: Record<PasswordScore, ProgressColor> = {\n  0: 'danger',\n  1: 'danger',\n  2: 'warning',\n  3: 'success',\n  4: 'success',\n};\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function RegisterBlock() {\n  const [firstName, setFirstName] = useState('');\n  const [lastName, setLastName] = useState('');\n  const [phone, setPhone] = useState('');\n  const [password, setPassword] = useState('');\n  const [terms, setTerms] = useState(false);\n  const [submitted, setSubmitted] = useState(false);\n  const [loading, setLoading] = useState(false);\n\n  const strength = passwordStrength(password);\n  const rules = [\n    { ok: strength.checks.length, text: 'Kamida 8 ta belgi' },\n    { ok: strength.checks.upper && strength.checks.lower, text: 'Katta va kichik harf' },\n    { ok: strength.checks.digit, text: 'Kamida bitta raqam' },\n    { ok: strength.checks.symbol, text: 'Maxsus belgi (!, ?, #)' },\n  ];\n\n  const validate = (): Errors => {\n    const next: Errors = {};\n    if (!firstName.trim()) next.firstName = 'Ismingizni kiriting';\n    if (!lastName.trim()) next.lastName = 'Familiyangizni kiriting';\n    const parsed = parsePhone(phone);\n    if (!phone) next.phone = 'Telefon raqamini kiriting';\n    else if (!parsed.valid) next.phone = \"Raqam to'liq yoki to'g'ri emas\";\n    if (strength.score < 2) next.password = 'Parol juda oddiy — yuqoridagi shartlarni bajaring';\n    if (!terms) next.terms = 'Davom etish uchun shartlarga rozilik bering';\n    return next;\n  };\n\n  // Birinchi yuborishdan keyin xatolar yozish paytida yangilanadi\n  const errors = submitted ? validate() : {};\n\n  const onSubmit = async (event: FormEvent) => {\n    event.preventDefault();\n    setSubmitted(true);\n    if (Object.keys(validate()).length > 0) return;\n    setLoading(true);\n    await wait(1000); // Haqiqiy ilovada — API so'rovi\n    setLoading(false);\n    toast.success('Hisob yaratildi', {\n      description: `+998 ${phone.slice(0, 2)} *** ** ${phone.slice(-2)} raqamiga SMS kod yuborildi`,\n    });\n  };\n\n  return (\n    <div className=\"@container w-full bg-surface-muted font-sans text-text\">\n      <div className=\"flex min-h-[720px] flex-col items-center justify-center gap-6 px-4 py-10\">\n        <div className=\"flex items-center gap-2.5\">\n          <span className=\"grid size-10 place-items-center rounded-xl bg-primary text-primary-foreground\">\n            <Store className=\"size-5\" aria-hidden=\"true\" />\n          </span>\n          <span className=\"text-lg font-bold\">Chorsu Market</span>\n        </div>\n\n        <Card className=\"w-full max-w-md @md:p-8\">\n          <form noValidate onSubmit={onSubmit} className=\"flex flex-col gap-5\">\n            <div className=\"flex flex-col gap-1.5 text-center\">\n              <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Hisob yaratish</h2>\n              <p className=\"m-0 text-sm text-text-muted\">\n                Bir daqiqada ro&apos;yxatdan o&apos;ting — 14 kun bepul\n              </p>\n            </div>\n\n            <div className=\"grid gap-4 @md:grid-cols-2\">\n              <Field label=\"Ism\" error={errors.firstName} required>\n                <Input\n                  value={firstName}\n                  onChange={(e) => setFirstName(e.target.value)}\n                  placeholder=\"Dilnoza\"\n                  autoComplete=\"given-name\"\n                />\n              </Field>\n              <Field label=\"Familiya\" error={errors.lastName} required>\n                <Input\n                  value={lastName}\n                  onChange={(e) => setLastName(e.target.value)}\n                  placeholder=\"Yusupova\"\n                  autoComplete=\"family-name\"\n                />\n              </Field>\n            </div>\n\n            <Field\n              label=\"Telefon raqami\"\n              description=\"Tasdiqlash kodi SMS orqali keladi\"\n              error={errors.phone}\n              required\n            >\n              <PhoneInput value={phone} onValueChange={setPhone} autoComplete=\"tel\" />\n            </Field>\n\n            <Field label=\"Parol\" error={errors.password} required>\n              <Input\n                type=\"password\"\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                autoComplete=\"new-password\"\n              />\n            </Field>\n\n            {/* Parol kuchi: chiziq + shartlar ro'yxati */}\n            <div className=\"-mt-2 flex flex-col gap-2\">\n              <Progress\n                size=\"sm\"\n                value={password ? strength.score + 1 : 0}\n                max={5}\n                color={SCORE_COLOR[strength.score]}\n                label={\n                  <span className=\"text-xs text-text-muted\">\n                    Parol kuchi:{' '}\n                    <span className=\"font-medium text-text\">{password ? strength.label : '—'}</span>\n                  </span>\n                }\n              />\n              <ul className=\"m-0 grid list-none gap-1 p-0 @md:grid-cols-2\">\n                {rules.map((rule) => (\n                  <li\n                    key={rule.text}\n                    className={\n                      rule.ok\n                        ? 'flex items-center gap-1.5 text-xs text-success'\n                        : 'flex items-center gap-1.5 text-xs text-text-muted'\n                    }\n                  >\n                    {rule.ok ? (\n                      <Check className=\"size-3.5 shrink-0\" aria-hidden=\"true\" />\n                    ) : (\n                      <X className=\"size-3.5 shrink-0\" aria-hidden=\"true\" />\n                    )}\n                    {rule.text}\n                    <span className=\"sr-only\">{rule.ok ? ' — bajarildi' : ' — bajarilmagan'}</span>\n                  </li>\n                ))}\n              </ul>\n            </div>\n\n            <Field error={errors.terms}>\n              <Checkbox\n                checked={terms}\n                onCheckedChange={setTerms}\n                invalid={Boolean(errors.terms)}\n                label={\n                  <>\n                    <a href=\"#terms\" className=\"font-medium text-link hover:underline\">\n                      Foydalanish shartlari\n                    </a>{' '}\n                    va{' '}\n                    <a href=\"#privacy\" className=\"font-medium text-link hover:underline\">\n                      maxfiylik siyosati\n                    </a>\n                    ga roziman\n                  </>\n                }\n              />\n            </Field>\n\n            <Button\n              type=\"submit\"\n              variant=\"primary\"\n              fullWidth\n              loading={loading}\n              leftIcon={<UserPlus />}\n            >\n              Ro&apos;yxatdan o&apos;tish\n            </Button>\n\n            <p className=\"m-0 text-center text-sm text-text-muted\">\n              Hisobingiz bormi?{' '}\n              <a href=\"#login\" className=\"font-medium text-link hover:underline\">\n                Kirish\n              </a>\n            </p>\n          </form>\n        </Card>\n      </div>\n    </div>\n  );\n}\n" },
  "settings-profile": { component: Block8, file: "settings-profile/settings-profile.tsx", meta: {"title":{"uz":"Profil sozlamalari","en":"Profile settings"},"description":{"uz":"Avatar yuklash, ism, email, telefon va RegionSelect — @akhatmirzo/ui/form va zUz bilan validatsiya.","en":"Avatar upload, name, email, phone and RegionSelect — validated with @akhatmirzo/ui/form and zUz."},"dependencies":["@akhatmirzo/core","@hookform/resolvers","lucide-react","react-hook-form","zod"],"category":"settings"}, source: "'use client';\n\nimport { UZ_REGIONS, formatPhone } from '@akhatmirzo/core';\nimport { zUz } from '@akhatmirzo/core/zod';\nimport {\n  Avatar,\n  Button,\n  Card,\n  Input,\n  PhoneInput,\n  RegionSelect,\n  Switch,\n  Textarea,\n  toast,\n} from '@akhatmirzo/ui';\nimport { Form, FormField, FormRootError, FormSubmit } from '@akhatmirzo/ui/form';\nimport { zodResolver } from '@hookform/resolvers/zod';\nimport { ImageUp, Trash2 } from 'lucide-react';\nimport { useRef } from 'react';\nimport { useForm, useWatch } from 'react-hook-form';\nimport { z } from 'zod';\n\nconst schema = z.object({\n  avatar: z.string().nullable(),\n  fullName: z\n    .string()\n    .trim()\n    .min(3, \"Ism va familiyani to'liq kiriting\")\n    .max(60, 'Juda uzun — 60 belgigacha'),\n  email: zUz.email(),\n  phone: zUz.phone(),\n  region: zUz.region(),\n  bio: z.string().max(160, \"Ko'pi bilan 160 belgi\").optional(),\n  newsletter: z.boolean(),\n});\n\ntype ProfileInput = z.input<typeof schema>;\ntype Profile = z.output<typeof schema>;\n\nconst DEFAULTS: ProfileInput = {\n  avatar: null,\n  fullName: 'Dilnoza Yusupova',\n  email: 'dilnoza@chorsu.uz',\n  phone: '901234567',\n  region: 'tashkent-city',\n  bio: \"Chorsu Market'da mahsulot menejeri. Milliy hunarmandchilik mahsulotlari bo'yicha mas'ul.\",\n  newsletter: true,\n};\n\n/** Avatar uchun eng katta fayl hajmi */\nconst MAX_AVATAR_BYTES = 2 * 1024 * 1024;\n\nconst wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport default function SettingsProfileBlock() {\n  const form = useForm<ProfileInput, unknown, Profile>({\n    resolver: zodResolver(schema),\n    defaultValues: DEFAULTS,\n  });\n  const fullName = useWatch({ control: form.control, name: 'fullName' });\n  const fileRef = useRef<HTMLInputElement>(null);\n\n  const save = async (profile: Profile) => {\n    // Haqiqiy ilovada — API so'rovi. Sinov: \"band@misol.uz\" — server xatosi\n    await wait(1000);\n    if (profile.email === 'band@misol.uz') {\n      form.setError('root.server', {\n        message: \"Bu email boshqa hisobga bog'langan. Boshqa manzil kiriting.\",\n      });\n      return;\n    }\n    // Saqlangan qiymatlar — yangi \"boshlang'ich\" holat (PhoneInput 998 siz 9 raqam kutadi)\n    form.reset({ ...profile, phone: profile.phone.slice(3) });\n    toast.success('Profil saqlandi', {\n      description: `${formatPhone(`+${profile.phone}`)} · ${UZ_REGIONS.find((r) => r.id === profile.region)?.name ?? ''}`,\n    });\n  };\n\n  return (\n    <section className=\"@container w-full bg-background font-sans text-text\">\n      <Form form={form} onSubmit={save} className=\"flex flex-col gap-6 p-4 @3xl:p-8\">\n        <div className=\"flex flex-col gap-1\">\n          <h2 className=\"m-0 text-2xl font-bold tracking-tight\">Profil</h2>\n          <p className=\"m-0 text-sm text-text-muted\">\n            Bu ma&apos;lumotlar mijozlar va jamoa a&apos;zolariga ko&apos;rinadi.\n          </p>\n        </div>\n\n        <div className=\"grid gap-6 @4xl:grid-cols-[240px_minmax(0,1fr)] @4xl:gap-10\">\n          <div className=\"flex flex-col gap-1\">\n            <h3 className=\"m-0 text-base font-semibold\">Shaxsiy ma&apos;lumotlar</h3>\n            <p className=\"m-0 text-sm text-text-muted\">\n              Rasm, ism va aloqa ma&apos;lumotlari. Telefon raqami SMS orqali tasdiqlanadi.\n            </p>\n          </div>\n\n          <Card className=\"gap-6\">\n            {/* Maxsus boshqaruv — `render` bilan: rasm tanlash, ko'rish va o'chirish */}\n            <FormField\n              name=\"avatar\"\n              label=\"Profil rasmi\"\n              description=\"PNG yoki JPG, 2 MB gacha\"\n              render={({ value, onValueChange, id }) => {\n                const src = typeof value === 'string' ? value : undefined;\n                return (\n                  <div className=\"flex flex-wrap items-center gap-4\">\n                    <Avatar name={fullName} src={src} size=\"xl\" />\n                    <input\n                      ref={fileRef}\n                      id={id}\n                      type=\"file\"\n                      accept=\"image/png,image/jpeg\"\n                      className=\"sr-only\"\n                      tabIndex={-1}\n                      onChange={(event) => {\n                        const file = event.target.files?.[0];\n                        event.target.value = '';\n                        if (!file) return;\n                        if (file.size > MAX_AVATAR_BYTES) {\n                          toast.error('Rasm juda katta', {\n                            description: '2 MB gacha fayl tanlang',\n                          });\n                          return;\n                        }\n                        // Oldingi vaqtinchalik URL'ni bo'shatamiz (xotira oqmasligi uchun)\n                        if (src?.startsWith('blob:')) URL.revokeObjectURL(src);\n                        onValueChange(URL.createObjectURL(file));\n                      }}\n                    />\n                    <div className=\"flex flex-wrap gap-2\">\n                      <Button\n                        size=\"sm\"\n                        variant=\"outline\"\n                        leftIcon={<ImageUp />}\n                        onClick={() => fileRef.current?.click()}\n                      >\n                        Rasm yuklash\n                      </Button>\n                      {src && (\n                        <Button\n                          size=\"sm\"\n                          variant=\"ghost\"\n                          leftIcon={<Trash2 />}\n                          onClick={() => {\n                            if (src?.startsWith('blob:')) URL.revokeObjectURL(src);\n                            onValueChange(null);\n                          }}\n                        >\n                          O&apos;chirish\n                        </Button>\n                      )}\n                    </div>\n                  </div>\n                );\n              }}\n            />\n\n            <FormField name=\"fullName\" label=\"Ism va familiya\" required>\n              <Input autoComplete=\"name\" />\n            </FormField>\n\n            <div className=\"grid gap-6 @2xl:grid-cols-2\">\n              <FormField name=\"email\" label=\"Email\" required>\n                <Input type=\"email\" autoComplete=\"email\" placeholder=\"ism@misol.uz\" />\n              </FormField>\n              <FormField name=\"phone\" label=\"Telefon\" description=\"SMS kod yuboriladi\" required>\n                <PhoneInput autoComplete=\"tel\" />\n              </FormField>\n            </div>\n\n            <FormField\n              name=\"region\"\n              label=\"Hudud\"\n              description=\"Buyurtmalar shu hududdan yetkaziladi\"\n              required\n            >\n              <RegionSelect />\n            </FormField>\n\n            <FormField name=\"bio\" label=\"O'zingiz haqingizda\" description=\"160 belgigacha\">\n              <Textarea minRows={3} maxLength={160} showCount />\n            </FormField>\n\n            <FormField name=\"newsletter\">\n              <Switch label=\"Haftalik hisobot va aksiyalarni emailga yuborish\" />\n            </FormField>\n\n            <FormRootError />\n\n            <div className=\"flex flex-col-reverse gap-2 border-t border-border pt-6 @md:flex-row @md:justify-end\">\n              {/* Oxirgi saqlangan (yoki boshlang'ich) qiymatlarga qaytaradi */}\n              <Button variant=\"ghost\" onClick={() => form.reset()}>\n                Bekor qilish\n              </Button>\n              <FormSubmit>Saqlash</FormSubmit>\n            </div>\n          </Card>\n        </div>\n      </Form>\n    </section>\n  );\n}\n" },
};
